    CONSTRAINT ck_rcs_qty CHECK (qty>0 AND expected_end_at>actual_start_at AND (actual_end_at IS NULL OR actual_end_at>=actual_start_at)),
    CONSTRAINT ck_rcs_json CHECK (JSON_VALID(source_units_json) AND JSON_VALID(qualification_json) AND JSON_VALID(plan_json)),
    CONSTRAINT ck_rcs_close CHECK ((actual_end_at IS NULL AND close_command_no IS NULL) OR (actual_end_at IS NOT NULL AND close_command_no IS NOT NULL)),
    CONSTRAINT ck_rcs_clean CHECK ((cleaning_from IS NULL AND cleaning_until IS NULL AND cleaning_completed_at IS NULL AND cleaning_command_no IS NULL) OR (actual_end_at IS NOT NULL AND cleaning_from IS NOT NULL AND cleaning_until IS NOT NULL AND cleaning_until>=cleaning_from AND ((cleaning_completed_at IS NULL AND cleaning_command_no IS NULL) OR (cleaning_completed_at>=cleaning_from AND cleaning_command_no IS NOT NULL)))),
    CONSTRAINT ck_rcs_tenant_no CHECK (CHAR_LENGTH(TRIM(tenant_no))>0 AND CHAR_LENGTH(tenant_no)=CHAR_LENGTH(TRIM(tenant_no))),
    CONSTRAINT ck_rcs_created_by CHECK (CHAR_LENGTH(TRIM(created_by))>0 AND CHAR_LENGTH(created_by)=CHAR_LENGTH(TRIM(created_by))),
    CONSTRAINT ck_rcs_updated_by CHECK (CHAR_LENGTH(TRIM(updated_by))>0 AND CHAR_LENGTH(updated_by)=CHAR_LENGTH(TRIM(updated_by))),
    CONSTRAINT ck_rcs_entity_no CHECK (CHAR_LENGTH(TRIM(entity_no))>0 AND CHAR_LENGTH(entity_no)=CHAR_LENGTH(TRIM(entity_no))),
    CONSTRAINT ck_rcs_segment_no CHECK (CHAR_LENGTH(TRIM(segment_no))>0 AND CHAR_LENGTH(segment_no)=CHAR_LENGTH(TRIM(segment_no))),
    CONSTRAINT ck_rcs_occupation_no CHECK (CHAR_LENGTH(TRIM(occupation_no))>0 AND CHAR_LENGTH(occupation_no)=CHAR_LENGTH(TRIM(occupation_no))),
    CONSTRAINT ck_rcs_logical_demand_no CHECK (CHAR_LENGTH(TRIM(logical_demand_no))>0 AND CHAR_LENGTH(logical_demand_no)=CHAR_LENGTH(TRIM(logical_demand_no))),
    CONSTRAINT ck_rcs_previous_segment_no CHECK (previous_segment_no IS NULL OR (CHAR_LENGTH(TRIM(previous_segment_no))>0 AND CHAR_LENGTH(previous_segment_no)=CHAR_LENGTH(TRIM(previous_segment_no)))),
    CONSTRAINT ck_rcs_command_no CHECK (CHAR_LENGTH(TRIM(command_no))>0 AND CHAR_LENGTH(command_no)=CHAR_LENGTH(TRIM(command_no))),
    CONSTRAINT ck_rcs_resource_no CHECK (CHAR_LENGTH(TRIM(resource_no))>0 AND CHAR_LENGTH(resource_no)=CHAR_LENGTH(TRIM(resource_no))),
    CONSTRAINT ck_rcs_personnel_no CHECK (personnel_no IS NULL OR (CHAR_LENGTH(TRIM(personnel_no))>0 AND CHAR_LENGTH(personnel_no)=CHAR_LENGTH(TRIM(personnel_no)))),
    CONSTRAINT ck_rcs_source_group_ref CHECK (CHAR_LENGTH(TRIM(source_group_ref))>0 AND CHAR_LENGTH(source_group_ref)=CHAR_LENGTH(TRIM(source_group_ref))),
    CONSTRAINT ck_rcs_role_slot CHECK (CHAR_LENGTH(TRIM(role_slot))>0 AND CHAR_LENGTH(role_slot)=CHAR_LENGTH(TRIM(role_slot))),
    CONSTRAINT ck_rcs_source_units_hash CHECK (source_units_hash REGEXP '^[0-9a-f]{64}$'),
    CONSTRAINT ck_rcs_close_command_no CHECK (close_command_no IS NULL OR (CHAR_LENGTH(TRIM(close_command_no))>0 AND CHAR_LENGTH(close_command_no)=CHAR_LENGTH(TRIM(close_command_no)))),
    CONSTRAINT ck_rcs_cleaning_command_no CHECK (cleaning_command_no IS NULL OR (CHAR_LENGTH(TRIM(cleaning_command_no))>0 AND CHAR_LENGTH(cleaning_command_no)=CHAR_LENGTH(TRIM(cleaning_command_no))))
) ENGINE=InnoDB COMMENT='Permanent actual resource evidence';

CREATE TABLE mch_resource_occupation_bucket (
    id BIGINT NOT NULL AUTO_INCREMENT,
    tenant_no VARCHAR(32) NOT NULL DEFAULT 'MAIN',
    created_at DATETIME(3) NOT NULL,
    created_by VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    updated_at DATETIME(3) NOT NULL,
    updated_by VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    version BIGINT NOT NULL DEFAULT 0,
    deleted INT NOT NULL DEFAULT 0,
    entity_no VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    projection_no VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    occupation_no VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    segment_no VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    logical_demand_no VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    resource_no VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    bucket_no VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    start_at DATETIME(3) NOT NULL,
    end_at DATETIME(3) NOT NULL,
    category VARCHAR(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    qty INT NOT NULL,
    retired_at DATETIME(3) NULL,
    retire_command_no VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_rcb_no (tenant_no, entity_no, projection_no),
    UNIQUE KEY uk_rcb_projection (tenant_no, entity_no, occupation_no, segment_no, logical_demand_no, bucket_no, category),
    KEY idx_rcb_bucket (tenant_no, entity_no, resource_no, start_at, category),
    CONSTRAINT ck_rcb_base CHECK (deleted=0 AND version>=0),
    CONSTRAINT ck_rcb_qty CHECK (qty>0 AND category IN ('OCCUPIED','CLEANING')),
    CONSTRAINT ck_rcb_grid CHECK (MOD(MINUTE(start_at),5)=0 AND SECOND(start_at)=0 AND MICROSECOND(start_at)=0 AND end_at=TIMESTAMPADD(MINUTE,5,start_at)),
    CONSTRAINT ck_rcb_retired CHECK ((retired_at IS NULL AND retire_command_no IS NULL) OR (retired_at IS NOT NULL AND retire_command_no IS NOT NULL)),
    CONSTRAINT ck_rcb_tenant_no CHECK (CHAR_LENGTH(TRIM(tenant_no))>0 AND CHAR_LENGTH(tenant_no)=CHAR_LENGTH(TRIM(tenant_no))),
    CONSTRAINT ck_rcb_created_by CHECK (CHAR_LENGTH(TRIM(created_by))>0 AND CHAR_LENGTH(created_by)=CHAR_LENGTH(TRIM(created_by))),
    CONSTRAINT ck_rcb_updated_by CHECK (CHAR_LENGTH(TRIM(updated_by))>0 AND CHAR_LENGTH(updated_by)=CHAR_LENGTH(TRIM(updated_by))),
    CONSTRAINT ck_rcb_entity_no CHECK (CHAR_LENGTH(TRIM(entity_no))>0 AND CHAR_LENGTH(entity_no)=CHAR_LENGTH(TRIM(entity_no))),
    CONSTRAINT ck_rcb_projection_no CHECK (CHAR_LENGTH(TRIM(projection_no))>0 AND CHAR_LENGTH(projection_no)=CHAR_LENGTH(TRIM(projection_no))),
    CONSTRAINT ck_rcb_occupation_no CHECK (CHAR_LENGTH(TRIM(occupation_no))>0 AND CHAR_LENGTH(occupation_no)=CHAR_LENGTH(TRIM(occupation_no))),
    CONSTRAINT ck_rcb_segment_no CHECK (CHAR_LENGTH(TRIM(segment_no))>0 AND CHAR_LENGTH(segment_no)=CHAR_LENGTH(TRIM(segment_no))),
    CONSTRAINT ck_rcb_logical_demand_no CHECK (CHAR_LENGTH(TRIM(logical_demand_no))>0 AND CHAR_LENGTH(logical_demand_no)=CHAR_LENGTH(TRIM(logical_demand_no))),
    CONSTRAINT ck_rcb_resource_no CHECK (CHAR_LENGTH(TRIM(resource_no))>0 AND CHAR_LENGTH(resource_no)=CHAR_LENGTH(TRIM(resource_no))),
    CONSTRAINT ck_rcb_bucket_no CHECK (CHAR_LENGTH(TRIM(bucket_no))>0 AND CHAR_LENGTH(bucket_no)=CHAR_LENGTH(TRIM(bucket_no))),
    CONSTRAINT ck_rcb_category CHECK (CHAR_LENGTH(TRIM(category))>0 AND CHAR_LENGTH(category)=CHAR_LENGTH(TRIM(category))),
    CONSTRAINT ck_rcb_retire_command_no CHECK (retire_command_no IS NULL OR (CHAR_LENGTH(TRIM(retire_command_no))>0 AND CHAR_LENGTH(retire_command_no)=CHAR_LENGTH(TRIM(retire_command_no))))
) ENGINE=InnoDB COMMENT='Permanent actual resource evidence';

DELIMITER $$
CREATE TRIGGER trg_rco_immutable BEFORE UPDATE ON mch_resource_occupation
FOR EACH ROW
BEGIN
    IF NOT (BINARY NEW.id <=> BINARY OLD.id) OR
        NOT (BINARY NEW.tenant_no <=> BINARY OLD.tenant_no) OR
        NOT (BINARY NEW.created_at <=> BINARY OLD.created_at) OR
        NOT (BINARY NEW.created_by <=> BINARY OLD.created_by) OR
        NOT (BINARY NEW.deleted <=> BINARY OLD.deleted) OR
        NOT (BINARY NEW.entity_no <=> BINARY OLD.entity_no) OR
        NOT (BINARY NEW.store_no <=> BINARY OLD.store_no) OR
        NOT (BINARY NEW.occupation_no <=> BINARY OLD.occupation_no) OR
        NOT (BINARY NEW.owner_no <=> BINARY OLD.owner_no) OR
        NOT (BINARY NEW.execution_no <=> BINARY OLD.execution_no) OR
        NOT (BINARY NEW.start_command_no <=> BINARY OLD.start_command_no) OR
        NOT (BINARY NEW.payload_hash <=> BINARY OLD.payload_hash) OR
        NOT (BINARY NEW.planned_resource_command_no <=> BINARY OLD.planned_resource_command_no) OR
        NOT (BINARY NEW.planned_resource_command_hash <=> BINARY OLD.planned_resource_command_hash) OR
        NOT (BINARY NEW.reference_json <=> BINARY OLD.reference_json) OR
        NOT (BINARY NEW.reference_hash <=> BINARY OLD.reference_hash) OR
        NOT (BINARY NEW.initial_plan_json <=> BINARY OLD.initial_plan_json) OR
        NOT (BINARY NEW.plan_hash <=> BINARY OLD.plan_hash) OR
        NOT (BINARY NEW.result_no <=> BINARY OLD.result_no) OR
        NOT (BINARY NEW.result_revision <=> BINARY OLD.result_revision) OR
        NOT (BINARY NEW.result_hash <=> BINARY OLD.result_hash) OR
        NOT (BINARY NEW.initial_effects_json <=> BINARY OLD.initial_effects_json) OR
        NOT (BINARY NEW.initial_effects_hash <=> BINARY OLD.initial_effects_hash) OR
        NOT (BINARY NEW.started_at <=> BINARY OLD.started_at) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Immutable resource original';
    END IF;
    IF (OLD.state='ENDED' AND NEW.state<>'ENDED') OR (OLD.state='CLEANING' AND NEW.state NOT IN ('CLEANING','ENDED')) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Occupation lifecycle cannot reopen';
    END IF;
    IF NEW.revision<OLD.revision OR NEW.revision>OLD.revision+1 OR NEW.observation_epoch<OLD.observation_epoch OR NEW.observation_epoch>OLD.observation_epoch+1 OR (NEW.state<>OLD.state AND NEW.revision<>OLD.revision+1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Occupation lifecycle revision required';
    END IF;
END$$

CREATE TRIGGER trg_rco_no_delete BEFORE DELETE ON mch_resource_occupation
FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Resource evidence cannot be deleted';
END$$

CREATE TRIGGER trg_rcu_immutable BEFORE UPDATE ON mch_resource_occupation_unit
FOR EACH ROW
BEGIN
    IF NOT (BINARY NEW.id <=> BINARY OLD.id) OR
        NOT (BINARY NEW.tenant_no <=> BINARY OLD.tenant_no) OR
        NOT (BINARY NEW.created_at <=> BINARY OLD.created_at) OR
        NOT (BINARY NEW.created_by <=> BINARY OLD.created_by) OR
        NOT (BINARY NEW.deleted <=> BINARY OLD.deleted) OR
        NOT (BINARY NEW.entity_no <=> BINARY OLD.entity_no) OR
        NOT (BINARY NEW.occupation_unit_no <=> BINARY OLD.occupation_unit_no) OR
        NOT (BINARY NEW.occupation_no <=> BINARY OLD.occupation_no) OR
        NOT (BINARY NEW.start_command_no <=> BINARY OLD.start_command_no) OR
        NOT (BINARY NEW.logical_demand_no <=> BINARY OLD.logical_demand_no) OR
        NOT (BINARY NEW.origin <=> BINARY OLD.origin) OR
        NOT (BINARY NEW.reservation_unit_no <=> BINARY OLD.reservation_unit_no) OR
        NOT (BINARY NEW.hold_no <=> BINARY OLD.hold_no) OR
        NOT (BINARY NEW.booking_owner_no <=> BINARY OLD.booking_owner_no) OR
        NOT (BINARY NEW.source_line_ref <=> BINARY OLD.source_line_ref) OR
        NOT (BINARY NEW.allocation_revision <=> BINARY OLD.allocation_revision) OR
        NOT (BINARY NEW.source_bucket_no <=> BINARY OLD.source_bucket_no) OR
        NOT (BINARY NEW.qty <=> BINARY OLD.qty) OR
        NOT (BINARY NEW.consumed_at <=> BINARY OLD.consumed_at) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Immutable resource original';
    END IF;
END$$

CREATE TRIGGER trg_rcu_no_delete BEFORE DELETE ON mch_resource_occupation_unit
FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Resource evidence cannot be deleted';
END$$

CREATE TRIGGER trg_rcs_immutable BEFORE UPDATE ON mch_resource_occupation_segment
FOR EACH ROW
BEGIN
    IF NOT (BINARY NEW.id <=> BINARY OLD.id) OR
        NOT (BINARY NEW.tenant_no <=> BINARY OLD.tenant_no) OR
        NOT (BINARY NEW.created_at <=> BINARY OLD.created_at) OR
        NOT (BINARY NEW.created_by <=> BINARY OLD.created_by) OR
        NOT (BINARY NEW.deleted <=> BINARY OLD.deleted) OR
        NOT (BINARY NEW.entity_no <=> BINARY OLD.entity_no) OR
        NOT (BINARY NEW.segment_no <=> BINARY OLD.segment_no) OR
        NOT (BINARY NEW.occupation_no <=> BINARY OLD.occupation_no) OR
        NOT (BINARY NEW.logical_demand_no <=> BINARY OLD.logical_demand_no) OR
        NOT (BINARY NEW.previous_segment_no <=> BINARY OLD.previous_segment_no) OR
        NOT (BINARY NEW.command_no <=> BINARY OLD.command_no) OR
        NOT (BINARY NEW.resource_no <=> BINARY OLD.resource_no) OR
        NOT (BINARY NEW.personnel_no <=> BINARY OLD.personnel_no) OR
        NOT (BINARY NEW.source_group_ref <=> BINARY OLD.source_group_ref) OR
        NOT (BINARY NEW.role_slot <=> BINARY OLD.role_slot) OR
        NOT (BINARY NEW.qty <=> BINARY OLD.qty) OR
        NOT (BINARY NEW.source_units_json <=> BINARY OLD.source_units_json) OR
        NOT (BINARY NEW.source_units_hash <=> BINARY OLD.source_units_hash) OR
        NOT (BINARY NEW.qualification_json <=> BINARY OLD.qualification_json) OR
        NOT (BINARY NEW.plan_json <=> BINARY OLD.plan_json) OR
        NOT (BINARY NEW.actual_start_at <=> BINARY OLD.actual_start_at) OR
        NOT (BINARY NEW.expected_end_at <=> BINARY OLD.expected_end_at) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Immutable resource original';
    END IF;
    IF OLD.actual_end_at IS NOT NULL AND (NOT (BINARY NEW.actual_end_at <=> BINARY OLD.actual_end_at) OR
        NOT (BINARY NEW.close_command_no <=> BINARY OLD.close_command_no)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Segment close is permanent';
    END IF;
    IF OLD.cleaning_from IS NOT NULL AND (NOT (BINARY NEW.cleaning_from <=> BINARY OLD.cleaning_from) OR
        NOT (BINARY NEW.cleaning_until <=> BINARY OLD.cleaning_until)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cleaning policy interval is immutable';
    END IF;
    IF OLD.cleaning_completed_at IS NOT NULL AND (NOT (BINARY NEW.cleaning_completed_at <=> BINARY OLD.cleaning_completed_at) OR
        NOT (BINARY NEW.cleaning_command_no <=> BINARY OLD.cleaning_command_no)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cleaning completion is permanent';
    END IF;
END$$

CREATE TRIGGER trg_rcs_no_delete BEFORE DELETE ON mch_resource_occupation_segment
FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Resource evidence cannot be deleted';
END$$

CREATE TRIGGER trg_rcb_immutable BEFORE UPDATE ON mch_resource_occupation_bucket
FOR EACH ROW
BEGIN
    IF NOT (BINARY NEW.id <=> BINARY OLD.id) OR
        NOT (BINARY NEW.tenant_no <=> BINARY OLD.tenant_no) OR
        NOT (BINARY NEW.created_at <=> BINARY OLD.created_at) OR
        NOT (BINARY NEW.created_by <=> BINARY OLD.created_by) OR
        NOT (BINARY NEW.deleted <=> BINARY OLD.deleted) OR
        NOT (BINARY NEW.entity_no <=> BINARY OLD.entity_no) OR
        NOT (BINARY NEW.projection_no <=> BINARY OLD.projection_no) OR
        NOT (BINARY NEW.occupation_no <=> BINARY OLD.occupation_no) OR
        NOT (BINARY NEW.segment_no <=> BINARY OLD.segment_no) OR
        NOT (BINARY NEW.logical_demand_no <=> BINARY OLD.logical_demand_no) OR
        NOT (BINARY NEW.resource_no <=> BINARY OLD.resource_no) OR
        NOT (BINARY NEW.bucket_no <=> BINARY OLD.bucket_no) OR
        NOT (BINARY NEW.start_at <=> BINARY OLD.start_at) OR
        NOT (BINARY NEW.end_at <=> BINARY OLD.end_at) OR
        NOT (BINARY NEW.category <=> BINARY OLD.category) OR
        NOT (BINARY NEW.qty <=> BINARY OLD.qty) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Immutable resource original';
    END IF;
    IF OLD.retired_at IS NOT NULL AND (NOT (BINARY NEW.retired_at <=> BINARY OLD.retired_at) OR
        NOT (BINARY NEW.retire_command_no <=> BINARY OLD.retire_command_no)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Projection retirement is permanent';
    END IF;
END$$

CREATE TRIGGER trg_rcb_no_delete BEFORE DELETE ON mch_resource_occupation_bucket
FOR EACH ROW
BEGIN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Resource evidence cannot be deleted';
END$$

CREATE TRIGGER trg_rco_owner_immutable BEFORE UPDATE ON mch_booking_owner
FOR EACH ROW
BEGIN
    IF OLD.occupation_association_state<>'UNBOUND' AND (NOT (BINARY NEW.tenant_no <=> BINARY OLD.tenant_no) OR
        NOT (BINARY NEW.entity_no <=> BINARY OLD.entity_no) OR
        NOT (BINARY NEW.store_no <=> BINARY OLD.store_no) OR
        NOT (BINARY NEW.owner_no <=> BINARY OLD.owner_no) OR
        NOT (BINARY NEW.source_type <=> BINARY OLD.source_type) OR
        NOT (BINARY NEW.source_no <=> BINARY OLD.source_no) OR
        NOT (BINARY NEW.occupation_association_state <=> BINARY OLD.occupation_association_state) OR
        NOT (BINARY NEW.planned_resource_command_no <=> BINARY OLD.planned_resource_command_no) OR
        NOT (BINARY NEW.planned_resource_command_hash <=> BINARY OLD.planned_resource_command_hash) OR
        NOT (BINARY NEW.execution_reference_json <=> BINARY OLD.execution_reference_json) OR
        NOT (BINARY NEW.execution_reference_hash <=> BINARY OLD.execution_reference_hash) OR
        NOT (BINARY NEW.execution_plan_hash <=> BINARY OLD.execution_plan_hash) OR
        NOT (BINARY NEW.initial_start_command_no <=> BINARY OLD.initial_start_command_no) OR
        NOT (BINARY NEW.seal_command_no <=> BINARY OLD.seal_command_no) OR NEW.deleted<>0) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Occupation owner association is permanent';
    END IF;
END$$

CREATE TRIGGER trg_rco_owner_no_delete BEFORE DELETE ON mch_booking_owner
FOR EACH ROW
BEGIN
    IF OLD.occupation_association_state<>'UNBOUND' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual resource association cannot be deleted';
    END IF;
END$$

CREATE TRIGGER trg_rco_command_immutable BEFORE UPDATE ON mch_resource_command
FOR EACH ROW
BEGIN
    IF NOT (BINARY NEW.command_kind <=> BINARY OLD.command_kind) OR
        NOT (BINARY NEW.command_kind <=> BINARY OLD.command_kind) OR
        NOT (BINARY NEW.payload_schema <=> BINARY OLD.payload_schema) OR
        NOT (BINARY NEW.execution_reference_json <=> BINARY OLD.execution_reference_json) OR
        NOT (BINARY NEW.execution_reference_hash <=> BINARY OLD.execution_reference_hash) OR
        NOT (BINARY NEW.planned_resource_command_no <=> BINARY OLD.planned_resource_command_no) OR
        NOT (BINARY NEW.planned_resource_command_hash <=> BINARY OLD.planned_resource_command_hash) OR
        NOT (BINARY NEW.execution_plan_hash <=> BINARY OLD.execution_plan_hash) OR
        NOT (BINARY NEW.original_start_command_no <=> BINARY OLD.original_start_command_no) OR
        NOT (BINARY NEW.actor_namespace <=> BINARY OLD.actor_namespace) OR
        NOT (BINARY NEW.actor_provenance_hash <=> BINARY OLD.actor_provenance_hash) OR
        NOT (BINARY NEW.machine_purpose <=> BINARY OLD.machine_purpose) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Resource command kind and original are immutable';
    END IF;
    IF OLD.command_kind='OCCUPATION_V1' AND (NOT (BINARY NEW.tenant_no <=> BINARY OLD.tenant_no) OR
        NOT (BINARY NEW.entity_no <=> BINARY OLD.entity_no) OR
        NOT (BINARY NEW.store_no <=> BINARY OLD.store_no) OR
        NOT (BINARY NEW.command_no <=> BINARY OLD.command_no) OR
        NOT (BINARY NEW.owner_no <=> BINARY OLD.owner_no) OR
        NOT (BINARY NEW.action <=> BINARY OLD.action) OR
        NOT (BINARY NEW.request_key_hash <=> BINARY OLD.request_key_hash) OR
        NOT (BINARY NEW.payload_hash <=> BINARY OLD.payload_hash) OR
        NOT (BINARY NEW.frozen_payload <=> BINARY OLD.frozen_payload) OR
        NOT (BINARY NEW.initiated_by <=> BINARY OLD.initiated_by) OR NEW.deleted<>0) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual command original is permanent';
    END IF;
    IF OLD.command_kind='OCCUPATION_V1' AND OLD.status<>'ACCEPTED' AND (NOT (BINARY NEW.status <=> BINARY OLD.status) OR
        NOT (BINARY NEW.result_payload <=> BINARY OLD.result_payload) OR
        NOT (BINARY NEW.original_result_no <=> BINARY OLD.original_result_no) OR
        NOT (BINARY NEW.original_result_revision <=> BINARY OLD.original_result_revision) OR
        NOT (BINARY NEW.original_result_hash <=> BINARY OLD.original_result_hash) OR
        NOT (BINARY NEW.occupation_outcome <=> BINARY OLD.occupation_outcome) OR
        NOT (BINARY NEW.seal_no <=> BINARY OLD.seal_no) OR
        NOT (BINARY NEW.seal_revision <=> BINARY OLD.seal_revision) OR
        NOT (BINARY NEW.seal_hash <=> BINARY OLD.seal_hash)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Original occupation result is permanent';
    END IF;
END$$

CREATE TRIGGER trg_rco_command_no_delete BEFORE DELETE ON mch_resource_command
FOR EACH ROW
BEGIN
    IF OLD.command_kind='OCCUPATION_V1' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual resource association cannot be deleted';
    END IF;
END$$

CREATE TRIGGER trg_rco_consumed_immutable BEFORE UPDATE ON mch_booking_hold_unit
FOR EACH ROW
BEGIN
    IF OLD.consumed_at IS NOT NULL AND (NOT (BINARY NEW.tenant_no <=> BINARY OLD.tenant_no) OR
        NOT (BINARY NEW.entity_no <=> BINARY OLD.entity_no) OR
        NOT (BINARY NEW.unit_no <=> BINARY OLD.unit_no) OR
        NOT (BINARY NEW.hold_no <=> BINARY OLD.hold_no) OR
        NOT (BINARY NEW.bucket_no <=> BINARY OLD.bucket_no) OR
        NOT (BINARY NEW.allocation_revision <=> BINARY OLD.allocation_revision) OR
        NOT (BINARY NEW.qty <=> BINARY OLD.qty) OR
        NOT (BINARY NEW.source_line_ref <=> BINARY OLD.source_line_ref) OR
        NOT (BINARY NEW.consume_occupation_unit_no <=> BINARY OLD.consume_occupation_unit_no) OR
        NOT (BINARY NEW.consumed_at <=> BINARY OLD.consumed_at) OR
        NOT (BINARY NEW.consume_command_no <=> BINARY OLD.consume_command_no) OR NEW.deleted<>0 OR NEW.released_at IS NOT NULL OR NEW.release_command_no IS NOT NULL) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Booking consumption is permanent';
    END IF;
END$$

CREATE TRIGGER trg_rco_consumed_no_delete BEFORE DELETE ON mch_booking_hold_unit
FOR EACH ROW
BEGIN
    IF OLD.consumed_at IS NOT NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual resource association cannot be deleted';
    END IF;
END$$
DELIMITER ;
